INSERT INTO Truyen (MaTruyen, TenTruyen, Slug, MoTa, TacGia, TrangThai, ChinhSachTruyCap, GiaBan, LuotXem, LuotThich, NguoiTao, NgayTao, NgayCapNhat) VALUES
(1, N'Tiên Nghịch', N'tien-nghich', N'Một thiếu niên nghèo khó bước lên con đường nghịch thiên tu tiên, chống lại số mệnh đã định.', N'Nhĩ Căn', N'Hoàn thành', N'Paid', 35000, 5394, 111, 3, N'2026-02-05 13:37:48', N'2026-04-26 21:37:48'),
(2, N'Đấu Phá Thương Khung', N'dau-pha-thuong-khung', N'Thiên tài đấu khí sa sút, nhờ dược lão thức tỉnh mà trở lại đỉnh cao đại lục.', N'Thiên Tàm Thổ Đậu', N'Hoàn thành', N'Free', 0, 6229, 86, 4, N'2026-07-12 19:47:18', N'2026-09-29 03:47:18'),
(3, N'Vũ Động Càn Khôn', N'vu-dong-can-khon', N'Thiếu niên Lâm Động dùng tổ phù huyền bí từng bước leo lên đỉnh cao võ đạo.', N'Thiên Tàm Thổ Đậu', N'Đang phát hành', N'Free', 0, 4855, 66, 5, N'2026-08-28 14:47:57', N'2026-10-31 21:47:57'),
(4, N'Phàm Nhân Tu Tiên', N'pham-nhan-tu-tien', N'Một người bình thường, tư chất tầm thường, nhờ cẩn trọng và một bình nhỏ bí ẩn mà tu tiên.', N'Vong Ngữ', N'Hoàn thành', N'Paid', 35000, 5263, 69, 6, N'2026-04-03 11:01:00', N'2026-06-21 16:01:00'),
(5, N'Thôn Phệ Tinh Không', N'thon-phe-tinh-khong', N'Thời đại võ giả vũ trụ, La Phong từ một thiếu niên nghèo trở thành cường giả tinh không.', N'Ngã Cật Tây Hồng Thị', N'Hoàn thành', N'Paid', 30000, 3861, 49, 7, N'2026-05-01 14:48:32', N'2026-07-05 16:48:32'),
(6, N'Kiếm Lai', N'kiem-lai', N'Cậu bé mồ côi ở trấn nhỏ, mang theo thanh kiếm gãy đi qua giang hồ tìm lại chính mình.', N'Phong Hỏa Hí Chư Hầu', N'Đang phát hành', N'Paid', 25000, 4679, 94, 3, N'2026-08-01 20:08:28', N'2026-10-03 22:08:28'),
(7, N'Nguyên Tôn', N'nguyen-ton', N'Đại thiên thế giới thuộc về những người nắm giữ nguyên khí, Chu Nguyên bước lên con đường vương giả.', N'Thiên Tàm Thổ Đậu', N'Đang phát hành', N'Free', 0, 3212, 81, 4, N'2026-01-20 07:01:15', N'2026-03-11 17:01:15'),
(8, N'Hắc Ám Chi Tâm', N'hac-am-chi-tam', N'Cô gái mang trong tim sức mạnh bóng tối phải chọn giữa tình yêu và lời nguyền gia tộc.', N'Lam Phương Thảo', N'Hoàn thành', N'Free', 0, 2082, 54, 5, N'2025-10-28 04:39:48', N'2025-12-19 07:39:48'),
(9, N'Người Giữ Đèn Phố Cổ', N'nguoi-giu-den-pho-co', N'Người thợ sửa đèn ở phố cổ Hội An vô tình cuốn vào chuỗi vụ mất tích liên quan đến những ngọn đèn lồng cổ.', N'Đặng Minh Khôi', N'Đang phát hành', N'Free', 0, 3382, 46, 6, N'2026-07-20 21:32:41', N'2026-09-17 04:32:41'),
(10, N'Mùa Thu Hà Nội Ấy', N'mua-thu-ha-noi-ay', N'Hai người xa lạ gặp nhau giữa mùa thu Hà Nội, một năm sau họ mới nhận ra mình đã là một phần cuộc đời nhau.', N'Lam Phương Thảo', N'Hoàn thành', N'Paid', 30000, 4106, 35, 7, N'2026-01-11 06:51:06', N'2026-03-17 09:51:06'),
(11, N'Hồ Sơ Mật Sài Gòn 1975', N'ho-so-mat-sai-gon-1975', N'Những ngày cuối tháng Tư, một hồ sơ mật biến mất khỏi dinh Độc Lập và viên sĩ quan điều tra phải tìm ra sự thật.', N'Đặng Minh Khôi', N'Hoàn thành', N'Paid', 30000, 3360, 46, 3, N'2025-12-04 19:50:29', N'2026-01-31 01:50:29'),
(12, N'Linh Vực', N'linh-vuc', N'Một vùng đất chỉ tồn tại trong mộng cảnh, nơi những linh hồn lạc lối tìm đường về.', N'Thiên Tàm Thổ Đậu', N'Đang phát hành', N'Free', 0, 1549, 37, 4, N'2026-06-03 19:48:38', N'2026-07-08 23:48:38'),
(13, N'Long Tộc', N'long-toc', N'Chàng trai bình thường nhận thư mời vào học viện bí ẩn và biết mình mang dòng máu rồng.', N'Giang Nam', N'Hoàn thành', N'Paid', 30000, 3725, 112, 5, N'2026-07-11 20:46:40', N'2026-09-14 04:46:40'),
(14, N'Ma Thiên Ký', N'ma-thien-ky', N'Nữ ma tu bị phản bội trùng sinh về mười năm trước, quyết viết lại số phận của mình.', N'Bát Nguyệt Trường An', N'Đang phát hành', N'Paid', 25000, 2574, 43, 6, N'2026-08-18 01:58:58', N'2026-10-08 10:58:58'),
(15, N'Kẻ Trộm Ký Ức', N'ke-trom-ky-uc', N'Năm 2087, một tên trộm có thể đánh cắp ký ức người khác bị cuốn vào âm mưu của tập đoàn công nghệ.', N'Lam Phương Thảo', N'Đang phát hành', N'Free', 0, 2249, 43, 7, N'2026-04-10 16:45:08', N'2026-05-25 01:45:08'),
(16, N'Triều Đại Sau Ngai Vàng', N'trieu-dai-sau-ngai-vang', N'Câu chuyện về một thái giám và cuộc cờ quyền lực trong hậu cung triều Lê.', N'Đặng Minh Khôi', N'Đang phát hành', N'Paid', 25000, 2457, 36, 3, N'2026-05-08 06:39:09', N'2026-06-26 15:39:09');
