INSERT INTO ChuongTruyen (MaChuong, MaTruyen, SoThuTuChuong, TieuDe, NoiDung, MienPhi, LuotXem, NgayPhatHanh) VALUES
(1, 1, 1, N'Chương 1: Tiên môn đại hội', N'Tiếng gió xuyên qua rừng trúc, mang theo hơi lạnh của buổi sớm. Ánh mắt Vương Lâm chợt sáng lên: cơ duyên mà y chờ đợi bấy lâu rốt cuộc đã xuất hiện. Vương Lâm ngồi xuống bên vách đá, cảm nhận linh khí trong thiên địa chậm rãi tụ lại. (Chương 1 - Tiên Nghịch)', 1, 809, N'2026-02-07 19:37:48'),
(2, 1, 2, N'Chương 2: Bước chân vào tông môn', N'Vương Lâm ngồi xuống bên vách đá, cảm nhận linh khí trong thiên địa chậm rãi tụ lại. Tiếng gió xuyên qua rừng trúc, mang theo hơi lạnh của buổi sớm. Ánh mắt Vương Lâm chợt sáng lên: cơ duyên mà y chờ đợi bấy lâu rốt cuộc đã xuất hiện. (Chương 2 - Tiên Nghịch)', 1, 729, N'2026-02-14 16:37:48'),
